import { C, DARK, FONT } from"../../../data/constants.js";
import { Ico as UIco, I } from"../../../components/ui/Icon.jsx";
/**
 * AnalyseIAKit.jsx — Tokens & composants UI du wizard AnalyseIA.
 * Extrait de AnalyseIA.jsx sans aucune modification de code.
 */

// ── Tokens (thème DARK — aligné sur les autres pages dark de l'app) ──────────
// Fond et surfaces reprennent les tokens DARK.* partagés (page Accueil,
// Entraînement/Aujourd'hui) → même teinte partout, aucune valeur inventée.
const T = {
  bg:DARK.bgDeep, surf:DARK.surface, surfHi:DARK.surfaceHi, surfFlat:'#141922',
  bd:'rgba(255,255,255,0.08)', bdHi:'rgba(255,255,255,0.14)', bdAc:'rgba(60,91,255,0.45)',
  t1:DARK.text, t2:'rgba(246,247,249,0.75)', t3:'rgba(246,247,249,0.55)',
  t4:'rgba(246,247,249,0.38)', t5:'rgba(246,247,249,0.20)',
  ac:C.accent, acLt:DARK.accent, acDk:C.accentDk,
  acSoft:'rgba(60,91,255,0.16)', acGlow:'rgba(60,91,255,0.28)',
  green:'#12B76A', red:'#E5484D',
};
const F   = FONT;
const SER = FONT;
const MON ='"JetBrains Mono",ui-monospace,monospace';

const CARD = {
  background:   T.surf,
  border:`1px solid ${T.bd}`,
  borderRadius: 20,
  boxShadow:'0 8px 24px rgba(0,0,0,0.35)',
  padding:'20px 16px',
};

// ── CSS animation (un seul tag, injecté une fois) ─────────────────────────────
const CSS_ONCE =`
  @keyframes ob-breathe { 0%,100%{opacity:.5;transform:scale(1)} 50%{opacity:.85;transform:scale(1.04)} }
  @keyframes ob-pulse   { 0%,100%{opacity:.55} 50%{opacity:1} }
  @keyframes ob-spin    { to{transform:rotate(360deg)} }
  @keyframes ob-fadeUp  { from{transform:translateY(10px);opacity:0} to{transform:translateY(0);opacity:1} }
  .ob-tap { transition:transform .15s cubic-bezier(.4,0,.2,1),opacity .2s,background .2s,border-color .2s,box-shadow .2s; cursor:pointer; -webkit-tap-highlight-color:transparent; }
  .ob-tap:active { transform:scale(0.97); }
`;

let cssInjected = false;
function InjectCSS() {
  if (!cssInjected && typeof document !=='undefined') {
    if (!document.getElementById('ob-styles')) {
      const s = document.createElement('style');
      s.id ='ob-styles'; s.textContent = CSS_ONCE;
      document.head.appendChild(s);
    }
    cssInjected = true;
  }
  return null;
}

// ── Icônes SVG (line, pas d'emoji) ───────────────────────────────────────────
function OI({ n, sz=18, c="currentColor", s=1.6 }) {
  return <UIco name={n} size={sz} color={c} stroke={s}/>;
}

// ── Silhouette : vraies photos de référence (issues de l'infographie) ──────────
const POSE_IMGS = {
  face:"data:image/jpeg;base64,",
  dos:"data:image/jpeg;base64,",
  profil:"data:image/jpeg;base64,",
};
// Annotations par vue
const POSE_ANNOTS = {
  face:   ["Regard droit devant toi","Bras le long du corps","Ventre relâché","Pieds à largeur des épaules"],
  dos:    ["Dos droit, ne te cambre pas","Bras le long du corps","Pieds à largeur des épaules"],
  profil: ["Regard droit devant toi","Épaules relâchées","Ventre relâché","Poids du corps réparti"],
};
// ── PoseCard — mannequin gauche · titre numéroté + bullets + bouton droite ───
function PoseCard({ view, hint, filled, photo, onTap, index }) {
  const annots = POSE_ANNOTS[view] || [];
  const labelMap = { face:'De face', dos:'De dos', profil:'De profil' };
  const label = labelMap[view] || view;
  return (
    <button type="button" className="ob-tap" onClick={onTap}
      style={{ width:"100%", padding:0, borderRadius:20, overflow:"hidden",
        border:`1px solid ${filled?T.bdAc:T.bd}`,
        background:T.surf, display:"block",
        boxShadow: filled
          ?"0 4px 16px rgba(60,91,255,0.12)"
          :"0 2px 12px rgba(16,19,24,0.08)",
        position:"relative" }}>
      {filled ? (
        <div style={{ position:"relative" }}>
          <img src={photo} alt="photo"
            style={{ width:"100%", height:260, objectFit:"cover", display:"block" }}/>
          <div style={{ position:"absolute", top:10, right:10,
            background:T.ac, color:"#FFF", borderRadius:8,
            padding:"4px 12px", fontSize:10, fontWeight:700, letterSpacing:"0.1em" }}>
             AJOUTÉE
          </div>
        </div>
) : (
        <div style={{ display:"flex", minHeight:232 }}>
          {/* Mannequin — gauche */}
          <div style={{ width:"42%", overflow:"hidden", position:"relative",
            flexShrink:0,
            borderRight:`1px solid rgba(255,255,255,0.08)` }}>
            <img src={POSE_IMGS[view]} alt={view}
              style={{ position:"absolute", inset:0,
                width:"100%", height:"100%",
                objectFit:"cover", objectPosition:"50% 8%",
                pointerEvents:"none", userSelect:"none" }}/>
          </div>

          {/* Contenu — droite */}
          <div style={{ flex:1, padding:"16px 16px 16px",
            display:"flex", flexDirection:"column", gap:12 }}>
            {/* Titre numéroté */}
            <div style={{ display:"flex", alignItems:"center", gap:8 }}>
              <span style={{ width:26, height:26, borderRadius:"50%",
                background:T.ac, color:"#FFF", fontSize:13, fontWeight:700,
                fontFamily:F, display:"grid", placeItems:"center", flexShrink:0 }}>
                {index}
              </span>
              <span style={{ fontSize:14, fontWeight:700, color:T.t1, fontFamily:F }}>
                {label}
              </span>
            </div>

            {/* Bullets */}
            <div style={{ display:"flex", flexDirection:"column", gap:8, flex:1 }}>
              {annots.map((txt,i) => (
                <div key={i} style={{ display:"flex", alignItems:"flex-start", gap:8 }}>
                  <svg width="10" height="10" viewBox="0 0 10 10"
                    style={{ flexShrink:0, marginTop:4 }}>
                    <circle cx="5" cy="5" r="4" fill="none" stroke={C.accent} strokeWidth="1.5"/>
                    <circle cx="5" cy="5" r="1.5" fill={C.accent}/>
                  </svg>
                  <span style={{ fontSize:11, color:T.t2, lineHeight:1.4,
                    fontFamily:F, fontWeight:500 }}>{txt}</span>
                </div>
))}
            </div>

            {/* Bouton + légende */}
            <div>
              <div style={{ display:"flex", alignItems:"center", justifyContent:"center",
                gap:8, background:`linear-gradient(145deg,${T.ac},${T.acDk})`,
                color:"#FFF", padding:"12px 12px", borderRadius:12,
                fontSize:13, fontWeight:700, fontFamily:F,
                boxShadow:"0 5px 16px -4px rgba(60,91,255,0.65)" }}>
                <OI n="camera" sz={15} s={1.9} c="#FFF"/>
                Galerie ou photo
              </div>
              <div style={{ textAlign:"center", marginTop:8,
                fontSize:10, color:T.t4, fontFamily:F }}>{hint}</div>
            </div>
          </div>
        </div>
)}
    </button>
);
}

// ── Stepper segmenté — cercles icônes (photo 3) ──────────────────────────────
function Stepper({ step, eyebrow, title, subtitle }) {
  const steps = [
    { label:'Photo',    icon:'camera'  },
    { label:'Profil',   icon:'person'  },
    { label:'Objectif', icon:'target'  },
    { label:'Santé',    icon:'heart'   },
    { label:'Matériel', icon:'barbell' },
  ];
  const total = steps.length;
  return (
    <div style={{ padding:'28px 20px 0' }}>
      {/* Cercles + ligne */}
      <div style={{ position:'relative', display:'flex',
        alignItems:'flex-start', justifyContent:'space-between' }}>
        {/* Ligne fond */}
        <div style={{ position:'absolute', top:18, left:'9%', right:'9%',
          height:2, background:'rgba(255,255,255,0.08)', zIndex:0 }}/>
        {/* Ligne active */}
        <div style={{ position:'absolute', top:18, left:'9%',
          width: step===0?'0%':`${Math.min((step/(total-1))*82,82)}%`,
          height:2, background:T.ac, zIndex:0, transition:'width .4s' }}/>
        {steps.map((s,i) => {
          const done = i < step, cur = i === step;
          return (
            <div key={i} style={{ display:'flex', flexDirection:'column',
              alignItems:'center', gap:4, position:'relative', zIndex:1 }}>
              <div style={{
                width:36, height:36, borderRadius:'50%',
                background: cur ? T.ac : done ? T.surfHi : T.surf,
                display:'grid', placeItems:'center',
                boxShadow: cur
                  ?`0 4px 12px ${T.acGlow}, 0 0 0 4px rgba(60,91,255,0.12)`
                  :'none',
                border: cur ?'none' :`1.5px solid rgba(255,255,255,0.12)`,
              }}>
                {/* <I> (monochrome) et non <OI> : Ico bascule sur la version
                    duotone pour ces noms et ignore alors la couleur demandée,
                    d'où le bleu résiduel dans les icônes inactives. */}
                <I name={s.icon} size={16} stroke={1.8}
                   color={cur ?'#FFF' : done ? T.t2 : T.t4}/>
              </div>
              <span style={{ fontFamily:MON, fontSize:7.5,
                fontWeight:cur?600:400, letterSpacing:"0.1em",
                textTransform:'uppercase', whiteSpace:'nowrap',
                color: cur?T.ac : done?T.t3 : T.t4 }}>
                {s.label}
              </span>
            </div>
);
        })}
      </div>
      {/* Eyebrow + title */}
      <div style={{ marginTop:20 }}>
        <div style={{ display:'flex', alignItems:'center', gap:8 }}>
          <span style={{ fontFamily:MON, fontSize:10, fontWeight:600, color:T.ac,
                         letterSpacing:"0.1em", textTransform:'uppercase' }}>
            ÉTAPE {step+1}/{total}
          </span>
          <span style={{ width:14, height:1, background:T.t5 }}/>
          <span style={{ fontFamily:MON, fontSize:10, fontWeight:500, color:T.t3,
                         letterSpacing:"0.1em", textTransform:'uppercase' }}>
            {eyebrow}
          </span>
        </div>
        <div style={{ fontFamily:SER, fontSize:34, fontWeight:400, letterSpacing:-1,
                      color:T.t1, lineHeight:1, marginTop:8 }}>
          {title}
        </div>
        {subtitle && (
          <div style={{ fontSize:13, fontWeight:500, color:T.t3, lineHeight:1.5, marginTop:8, maxWidth:330 }}>
            {subtitle}
          </div>
)}
      </div>
    </div>
);
}

// ── NavButtons ────────────────────────────────────────────────────────────────
function NavBtns({ nextLabel, enabled, gen, onNext, onBack, showBack=true }) {
  return (
    <div style={{ padding:'24px 20px 0', display:'flex', flexDirection:'column', gap:8 }}>
      <button className="ob-tap" onClick={enabled?onNext:undefined} style={{
        width:'100%', padding:'16px', borderRadius:16,
        background: enabled
          ?`linear-gradient(180deg,${T.acLt} 0%,${T.ac} 50%,${T.acDk} 100%)`
          : T.surfHi,
        color: enabled ? T.t1 : T.t4,
        border:`1px solid ${enabled?T.acLt+'60':T.bd}`,
        display:'flex', alignItems:'center', justifyContent:'center', gap:8,
        fontFamily:F, fontSize:14, fontWeight:600, letterSpacing:0.2,
        boxShadow: enabled
          ?'inset 0 1px 0 rgba(0,0,0,0.12), 0 8px 22px rgba(45,93,201,0.35)'
          :'none',
        opacity: enabled ? 1 : 0.65,
      }}>
        {gen && <OI n="sparkles" sz={15} s={1.9} c={enabled?T.t1:T.t4}/>}
        {nextLabel}
        {!gen && <OI n="arrowR" sz={14} s={1.9} c={enabled?T.t1:T.t4}/>}
      </button>
      {showBack && onBack && (
        <button className="ob-tap" onClick={onBack} style={{
          width:'100%', padding:'16px', borderRadius:16,
          background:'transparent', color:T.t3, border:`1px solid ${T.bd}`,
          display:'flex', alignItems:'center', justifyContent:'center', gap:8,
          fontFamily:F, fontSize:13, fontWeight:600,
        }}>
          <OI n="arrowL" sz={13} s={1.9}/> Retour
        </button>
)}
    </div>
);
}

// ── FieldLabel ────────────────────────────────────────────────────────────────
function FL({ children, required, optional }) {
  return (
    <div style={{ fontFamily:F, fontSize:11, fontWeight:600, color:T.t3,
                  letterSpacing:0.2, marginBottom:8,
                  display:'flex', alignItems:'center', gap:4 }}>
      <span>{children}</span>
      {required && <span style={{ color:T.ac }}>*</span>}
      {optional && <span style={{ fontFamily:MON, fontSize:8, color:T.t5,
                                  letterSpacing:"0.1em", textTransform:'uppercase' }}>FACULTATIF</span>}
    </div>
);
}
// ── SelectRow (niveau d'expérience) ──────────────────────────────────────────
function SelRow({ label, meta, selected, onClick }) {
  return (
    <button className="ob-tap" onClick={onClick} style={{
      width:'100%', padding:'16px 16px', borderRadius:16, textAlign:'left',
      background: selected ?`linear-gradient(95deg,${T.acSoft},${T.surf} 75%)` : T.surf,
      border:`1px solid ${selected?T.bdAc:T.bd}`,
      display:'flex', alignItems:'center', justifyContent:'space-between', gap:12,
    }}>
      <div style={{ display:'flex', alignItems:'center', gap:12 }}>
        <span style={{ width:18, height:18, borderRadius:'50%',
          border:`1.5px solid ${selected?T.ac:T.bdHi}`,
          display:'grid', placeItems:'center',
          background:selected?T.ac:'transparent', flexShrink:0 }}>
          {selected && <span style={{ width:7, height:7, borderRadius:'50%', background:'#FFF' }}/>}
        </span>
        <span style={{ fontFamily:F, fontSize:14, fontWeight:600, color:T.t1 }}>{label}</span>
      </div>
      <span style={{ fontFamily:MON, fontSize:11, color:selected?T.acLt:T.t4 }}>{meta}</span>
    </button>
);
}

// ── GoalCard ─────────────────────────────────────────────────────────────────
const GOAL_ICONS = {
  hypertrophie:'muscle', force:'barbell', poids:'flame',
  prep_physique:'zap', reathletisation:'pulse', sante:'heart',
};
// Chaque objectif a sa couleur sémantique — comme les intensités du programme
const GOAL_COLORS = {
  // Charte MorphoCoach : bleu en accent principal, dégradés bleutés pour
  // différencier — plus de rouge / jaune / vert sur ces cartes.
  hypertrophie:'#3C5BFF',
  force:'#3C5BFF',
  poids:'#3C5BFF',
  prep_physique:'#6E86FF',
  reathletisation:'#9DB0FF',
  sante:'#6E86FF',
};
function GoalCrd({ id, label, selected, onClick }) {
  const ic  = GOAL_ICONS[id]  ||'zap';
  const col = GOAL_COLORS[id] || T.ac;
  return (
    <button className="ob-tap" onClick={onClick} style={{
      padding:'20px 16px 16px', borderRadius:16, textAlign:'center',
      position:'relative', overflow:'hidden',
      background: selected
        ?`linear-gradient(155deg, ${col} 0%, ${col}CC 55%, ${col}66 100%)`
        : T.surf,
      border:`1px solid ${selected ? col+'60' : T.bd}`,
      display:'flex', flexDirection:'column', alignItems:'center', gap:12,
      boxShadow: selected ?`0 16px 32px ${col}35` :'none',
    }}>
      {selected && <div style={{ position:'absolute', top:0, left:0, right:0, height:1,
        background:'linear-gradient(90deg,transparent,rgba(255,255,255,0.10),transparent)' }}/>}
      {selected && <div style={{ position:'absolute', inset:0, pointerEvents:'none',
        background:'radial-gradient(160% 60% at 20% 10%, rgba(255,255,255,0.07), transparent 55%)' }}/>}
      {selected && (
        <div style={{ position:'absolute', top:8, right:8, width:20, height:20,
          borderRadius:'50%', background:'rgba(255,255,255,0.95)',
          border:'1px solid rgba(255,255,255,0.65)',
          display:'grid', placeItems:'center' }}>
          <OI n="check" sz={11} s={2.8} c={col}/>
        </div>
)}
      <div style={{ width:44, height:44, borderRadius:12,
        background: selected ?'rgba(255,255,255,0.25)' :`${col}18`,
        border:`1px solid ${selected ?'rgba(255,255,255,0.35)' : col+'35'}`,
        display:'grid', placeItems:'center',
        color: selected ?'#FFF' : col }}>
        <OI n={ic} sz={21} s={1.7}/>
      </div>
      <span style={{ fontFamily:F, fontSize:13, fontWeight:700,
        color: selected ?'#FFF' : T.t2, letterSpacing:-0.2,
        textShadow:'none' }}>
        {label}
      </span>
    </button>
);
}

// ── EquipCard ─────────────────────────────────────────────────────────────────
const EQUIP_ICONS = {
  salle_complete:'building', halteres:'dumbbell', elastiques:'band',
  barre_traction:'pullup',   poids_corps:'person', machines:'gear',
};
const EQUIP_COLORS = {
  salle_complete:C.accent, halteres:'#3C5BFF', elastiques:'#12B76A',
  barre_traction:'#F59E0B', poids_corps:'#3C5BFF', machines:'#3C5BFF',
};
function EquipCrd({ id, label, selected, onClick }) {
  const ic = EQUIP_ICONS[id] ||'gear';
  const col = EQUIP_COLORS[id] || C.accent;
  return (
    <button className="ob-tap" onClick={onClick} style={{
      padding:'20px 16px', borderRadius:16, textAlign:'center',
      position:'relative', overflow:'hidden',
      background: selected ?`linear-gradient(180deg,${T.surfHi},${T.surf})` : T.surf,
      border:`1px solid ${selected?T.bdAc:T.bd}`,
      display:'flex', flexDirection:'column', alignItems:'center', gap:12,
      boxShadow: selected ?'0 8px 22px rgba(45,93,201,0.25)' :'none',
      opacity: selected ? 1 : 0.62,
    }}>
      {selected && (
        <div style={{ position:'absolute', top:8, right:8, width:18, height:18,
          borderRadius:'50%', background:T.ac, display:'grid', placeItems:'center' }}>
          <OI n="check" sz={11} s={2.8} c="#FFF"/>
        </div>
)}
      <div style={{ width:44, height:44, borderRadius:12,
        background:`linear-gradient(145deg,${col},${col}DD)`,
        boxShadow:`0 4px 12px ${col}45`,
        display:'grid', placeItems:'center', color:'#FFF' }}>
        <OI n={ic} sz={21} s={1.8} c="#FFF"/>
      </div>
      <span style={{ fontFamily:F, fontSize:13, fontWeight:600,
                     color:selected?T.t1:T.t2 }}>{label}</span>
    </button>
);
}

// ── Chip (pathologies) ────────────────────────────────────────────────────────
function Chip({ label, selected, onClick }) {
  return (
    <button className="ob-tap" onClick={onClick} style={{
      padding:'8px 16px', borderRadius:999,
      background:selected?T.acSoft:T.surf,
      border:`1px solid ${selected?T.bdAc:T.bd}`,
      color:selected?T.acLt:T.t3,
      fontFamily:F, fontSize:13, fontWeight:600, letterSpacing:0.2,
      display:'flex', alignItems:'center', gap:8, whiteSpace:'nowrap',
    }}>
      {selected && <OI n="check" sz={11} s={2.6} c={T.acLt}/>}
      {label}
    </button>
);
}

// ── ZoneGroup (pathologies) ───────────────────────────────────────────────────
const ZONE_ICONS = { Dos:'spine', Épaule:'shoulder', Genou:'knee', Autres:'bone' };
function ZoneGrp({ zone, items, selected, onToggle }) {
  return (
    <div style={{ marginBottom:20 }}>
      <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:12 }}>
        <div style={{ width:24, height:24, borderRadius:8,
          background:'rgba(255,255,255,0.05)', border:`1px solid ${T.bd}`,
          display:'grid', placeItems:'center', color:T.t3 }}>
          <OI n={ZONE_ICONS[zone]||'more'} sz={13} s={1.6}/>
        </div>
        <span style={{ fontFamily:MON, fontSize:10, fontWeight:500, color:T.t3,
                       letterSpacing:"0.1em", textTransform:'uppercase' }}>{zone}</span>
      </div>
      <div style={{ display:'flex', flexWrap:'wrap', gap:8 }}>
        {items.map(p => (
          <Chip key={p} label={p} selected={selected.includes(p)} onClick={()=>onToggle(p)}/>
))}
      </div>
    </div>
);
}

// ── DayPicker ─────────────────────────────────────────────────────────────────
function DayPicker({ selected, onToggle }) {
  return (
    <div style={{ display:'flex', gap:4 }}>
      {["Lun","Mar","Mer","Jeu","Ven","Sam","Dim"].map(d => {
        const on = selected.includes(d);
        return (
          <button key={d} className="ob-tap" onClick={()=>onToggle(d)} style={{
            flex:1, padding:'12px 0', borderRadius:12,
            background: on ?`linear-gradient(160deg,${T.acLt},${T.acDk})` : T.surf,
            border:`1px solid ${on?T.acLt:T.bd}`,
            color: on ?'#FFF' : T.t3,
            fontFamily:F, fontSize:11, fontWeight:600, letterSpacing:-0.2,
            boxShadow: on ?`0 4px 10px ${T.acGlow}` :'none',
          }}>{d}</button>
);
      })}
    </div>
);
}

// ════════════════════════════════════════════════════════════════════════════
// COMPOSANT PRINCIPAL — logique inchangée
// ════════════════════════════════════════════════════════════════════════════

export { T, F, SER, MON, CARD, CSS_ONCE, InjectCSS, OI, POSE_IMGS, POSE_ANNOTS, PoseCard, Stepper, NavBtns, FL, SelRow, GOAL_ICONS, GOAL_COLORS, GoalCrd, EQUIP_ICONS, EQUIP_COLORS, EquipCrd, Chip, ZONE_ICONS, ZoneGrp, DayPicker };
